/**
 * Shared state between global setup and the test workers.
 *
 * Only the second-factor secrets live here — the same values an authenticator app
 * would hold, for accounts in the disposable E2E database. The file is gitignored
 * (`.gitignore`: `e2e/.auth/`) and regenerated by global setup on every run.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

import type { AccountKey } from './accounts';

export interface MfaState {
  secret: string;
  /** Highest TOTP counter the server has already accepted for this account. */
  lastCounter: number | null;
}

export interface SuiteState {
  createdAt: string;
  apiOrigin: string;
  baseURL: string;
  /** Run ids that existed before the suite started, so a spec can spot its own. */
  baselineRunIds: string[];
  mfa: Partial<Record<AccountKey, MfaState>>;
}

export const AUTH_DIR = join(__dirname, '..', '.auth');
export const STATE_PATH = join(AUTH_DIR, 'state.json');

/** Where the signed-in cookie jar for a role is cached (`storageState`). */
export function storageStatePath(account: string): string {
  return join(AUTH_DIR, `${account}.json`);
}

export function readState(): SuiteState {
  if (!existsSync(STATE_PATH)) {
    throw new Error(
      `missing ${STATE_PATH} — global setup did not run. Start the suite with \`npm run e2e\`.`,
    );
  }
  return JSON.parse(readFileSync(STATE_PATH, 'utf8')) as SuiteState;
}

export function writeState(state: SuiteState): void {
  mkdirSync(dirname(STATE_PATH), { recursive: true });
  writeFileSync(STATE_PATH, `${JSON.stringify(state, null, 2)}\n`, { mode: 0o600 });
}

/** Persist an advanced counter so a later login never replays a spent code. */
export function commitMfaCounter(account: AccountKey, counter: number): void {
  const state = readState();
  const entry = state.mfa[account];
  if (!entry) throw new Error(`no stored second factor for ${account}`);
  entry.lastCounter = entry.lastCounter === null ? counter : Math.max(entry.lastCounter, counter);
  writeState(state);
}
